SourceCode.Declaration:
internal final class METSalesOrderShipmentConfirmation
{
    MetShipmentId       metShipmentId;
}

Method.Source:
static METSalesOrderShipmentConfirmation construct(MetShipmentId _shipmentid)
{
    if (!_shipmentid)
    {
        throw error(strFmt("@SYS19306", funcName()));
    }

    return new METSalesOrderShipmentConfirmation(_shipmentid);
}

public void run()
{
    #OCCRetryCount
    try
    {
        ttsBegin;
        boolean       isPosted;
        DocumentStatus  documentStatus;
        AccountOrder        accountOrder;
        METCustTable    metCustTable;
        METSalesOrderShipmentLoadHeader     shipmentLoadHeader;

        select firstonly shipmentLoadHeader
            where shipmentLoadHeader.ShipmentId == metShipmentId;

        metCustTable = metCustTable::find(shipmentLoadHeader.CustAccount);

        if (metCustTable.FinalizationDocument != METFinalizationDocument::None)
        {
            documentStatus = metCustTable.FinalizationDocument == METFinalizationDocument::Invoice ? DocumentStatus::Invoice : DocumentStatus::PackingSlip;
            accountOrder   = shipmentLoadHeader.PostMultiDocument == NoYes::No ? AccountOrder::Account : AccountOrder::None;

            isPosted = this.postPackingslipInvoiceReport(shipmentLoadHeader, documentStatus, accountOrder);
        }
        else
        {
            warning (strFmt("@MET:SOFinalisationDocCheck", shipmentLoadHeader.ShipmentId));
        }


        ttsCommit;

        if (isPosted)
        {
            METSalesOrderShipmentLoadHeader::updateDocStatusInHeader(MetShipmentStatus::Shipped, documentStatus, metShipmentId);
        }
        else
        {
            METSalesOrderShipmentLoadHeader::updateDocStatusInHeader(MetShipmentStatus::Open, documentStatus, metShipmentId);
        }

    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw;
        }
    }
    catch
    {
        exceptionTextFallThrough();
        //METSalesOrderShipmentLoadHeader::updateDocStatusInHeader(MetShipmentStatus::Open, DocumentStatus::None, MetShipmentId);
    }
}

/// <summary>
/// Method to post the invoice report
/// </summary>
/// <param name = "_accountOrder">Account order</param>
/// <returns>Boolean result</returns>
private boolean postPackingslipInvoiceReport(METSalesOrderShipmentLoadHeader    _shipmentLoadHeader, DocumentStatus _docStatus, AccountOrder _accountOrder)
{
    boolean                         isPosted = false;
    JournalId                       jourId;
    SalesFormLetter                 salesFormLetter;
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeader;

    salesFormLetter = SalesFormLetter::construct(_docStatus);

    salesFormLetter.chooseLinesQuery(this.calcQuery(_shipmentLoadHeader.ShipmentId));
    salesFormLetter.transDate(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()));
    salesFormLetter.specQty(SalesUpdate::PickingList);
    salesFormLetter.proforma(NoYes::No);
    salesFormLetter.printout(Printout::Current);
    salesFormLetter.printFormLetter(NoYes::No);
    salesFormLetter.usePrintManagement(NoYes::No);
    salesFormLetter.chooseLines(false, true);
    salesFormLetter.sumBy(_accountOrder); 
    salesFormLetter.reArrangeNow(!_shipmentLoadHeader.PostMultiDocument); 

    salesFormLetter.run();

    if (salesFormLetter.parmJournalRecord().TableId == tableNum(CustPackingSlipJour))
    {
        CustPackingSlipJour     jourTable;
        jourTable = salesFormLetter.parmJournalRecord();
        jourId  = jourTable.packingSlipId;

        if(jourTable)
        {
            if (!_shipmentLoadHeader.PostMultiDocument)
            {
                jourTable.METUpdateLoadShipmentId(metSalesOrderShipmentLoadHeader);
            }
            else
            {
                CustPackingSlipJour::METUpdateLoadShipmentLines(metSalesOrderShipmentLoadHeader);
            }
            isPosted = true;
        }
    }
    else if(salesFormLetter.parmJournalRecord().TableId == tableNum(CustInvoiceJour))
    {
        CustInvoiceJour     jourTable;
        jourTable = salesFormLetter.parmJournalRecord();
        jourId  = jourTable.InvoiceId;

        if(jourTable)
        {
            if (!_shipmentLoadHeader.PostMultiDocument)
            {
                jourTable.METUpdateLoadShipmentId(metSalesOrderShipmentLoadHeader);
            }
            else
            {
                CustInvoiceJour::METUpdateLoadShipmentLines(metSalesOrderShipmentLoadHeader);
            }
            isPosted = true;
        }
    }

    return isPosted;
}

/// <summary>
/// Calculate query based on shipment Id
/// </summary>
/// <param name = "_shipmentId">Shipment Id reference</param>
/// <returns>SysQueryRun</returns>
private SysQueryRun calcQuery(WMSShipmentId _shipmentId)
{
    METSalesOrderShipmentLoadLines  metLines;
    RefRecId                salesLineRecId;
    Query                   qry = new Query(QueryStr(SalesUpdate));
    QueryBuildDataSource    queryBuildDataSource = qry.dataSourceTable(tableNum(SalesLine));
    QueryBuildRange         queryBuildRange;
    SalesLine               salesLine;

    while select metLines
            where metLines.ShipmentId == _shipmentId
        join RecId from salesLine
            where salesLine.SalesId == metLines.ordernum &&
                salesLine.LineNum == metLines.lineNum
    {
        salesLineRecId = salesLine.RecId;
        queryBuildRange = queryBuildDataSource.addRange(fieldnum(SalesLine, RecId));
        queryBuildRange.value(SysQuery::value(salesLineRecId));
    }
    return new sysQueryRun(qry);
}
